    cw = iw - 0.5;
    union() {
        cube([ol, ow, wall]);                                    // top plate, full footprint
        translate([(ol - cl) / 2, (ow - cw) / 2, 0])
            cube([cl, cw, wall + lip]);                          // plug (overlaps the plate -> one solid)
    }
}

box();
translate([0, ow + 10, 0]) lid();
